const nama = $json['Nama lengkap'] || $json.Nama || 'Peserta';
const rawWa = $json['Nomor WhatsApp (Aktif)'] || $json.Nomor_WA || '';

// Format nomor WA Indonesia
let cleanWa = String(rawWa).replace(/[^0-9]/g, '');
if (cleanWa.startsWith('0')) cleanWa = '62' + cleanWa.substring(1);
else if (cleanWa.startsWith('8')) cleanWa = '62' + cleanWa;

const hariTanggal = 'Senin, 31 Agustus 2026';
const waktu = '17.30 (Open Gate) - Selesai';
const lokasi = 'Ketintang Madya no.66';

const pesan = `Halo Kak ${nama}! 👋

Semoga sehat selalu ya.

Menjelang acara Welcome Maba 2026, kami dari tim panitia ingin melakukan konfirmasi kehadiran nih.

Apakah Kakak dipastikan bisa hadir di acara kita?

🗓 Hari/Tanggal: ${hariTanggal}
⏰ Waktu: ${waktu}
📍 Lokasi: ${lokasi}

Mohon balas pesan ini dengan format:

[Hadir / Tidak Hadir]

Konfirmasi Kakak sangat membantu kami dalam penyiapan tempat & konsumsi. Terima kasih banyak! 🙏✨`;

return {
  json: {
    ...$json,
    target_wa: cleanWa,
    pesan_formatted: pesan
  }
};
